class Type(Enum):
    """
    general = Aviso general (every plan); event, flash = Growth+.
    """

    general = "general"
    event = "event"
    flash = "flash"


class Audience(Enum):
    """
    Anything but all = Growth+.
    """

    all = "all"
    near = "near"
    inactive = "inactive"
    level = "level"
    location = "location"


class NotificationCreate(BaseModel):
    model_config = ConfigDict(
        extra="forbid",
    )
    type: Annotated[
        Type,
        Field(
            description="general = Aviso general (every plan); event, flash = Growth+."
        ),
    ]
    audience: Annotated[Audience, Field(description="Anything but all = Growth+.")]
    levelMin: Annotated[
        Optional[int],
        Field(None, description="Required when audience = level.", ge=2, le=50),
    ]
    locationId: Annotated[
        Optional[UUID], Field(None, description="Required when audience = location.")
    ]
    title: Annotated[
        Optional[str],
        Field(
            None,
            description="Message header; defaults to the business name.",
            max_length=60,
        ),
    ]
    body: Annotated[str, Field(max_length=150, min_length=1)]
    url: Annotated[
        Optional[str],
        Field(
            None,
            description='Optional "more information" link (Growth+); must relate to the program.',
            max_length=500,
            pattern="^https://",
        ),
    ]
    eventAt: Annotated[
        Optional[AwareDatetime],
        Field(
            None,
            description="Required when type = event. The message hides from the pass 6 h after it.",
        ),
    ]
    flashHours: Annotated[
        Optional[int],
        Field(
            None,
            description="Required when type = flash. The message hides from the pass when the offer closes.",
            ge=1,
            le=72,
        ),
    ]
    scheduledAt: Annotated[
        Optional[AwareDatetime],
        Field(
            None,
            description="Omit to send now; otherwise a future instant (max 60 days ahead).",
        ),
    ]


